import{_ as e,o,c as a,ag as n}from"./chunks/framework.B7PviQjB.js";const r="/docs/images/board/run-a-retro-template.png",s="/docs/images/board/run-a-retro-voting.png",i="/docs/images/board/run-a-retro-final.png",b=JSON.parse('{"title":"Run a retro on a board","description":"Run a Start, Stop, Continue retrospective on a board, from the template to a voted list of action items and a PDF.","frontmatter":{"title":"Run a retro on a board","description":"Run a Start, Stop, Continue retrospective on a board, from the template to a voted list of action items and a PDF.","type":"tutorial"},"headers":[],"relativePath":"board/run-a-retro.md","filePath":"board/run-a-retro.md"}'),l={name:"board/run-a-retro.md"};function c(d,t,h,p,u,g){return o(),a("div",null,[...t[0]||(t[0]=[n('<h1 id="run-a-retro-on-a-board" tabindex="-1">Run a retro on a board <a class="header-anchor" href="#run-a-retro-on-a-board" aria-label="Permalink to &quot;Run a retro on a board&quot;">​</a></h1><p>Run a Start, Stop, Continue retrospective on a board, from the template to a voted list of action items and a PDF. It takes about 15 minutes, and you learn the board&#39;s core tools on the way.</p><div class="info custom-block"><p class="custom-block-title">Before you start</p><ul><li>You need a workspace where you can create documents.</li><li>Teammates are optional. You can follow every step alone.</li></ul></div><h2 id="_1-start-from-the-retro-template" tabindex="-1">1. Start from the Retro template <a class="header-anchor" href="#_1-start-from-the-retro-template" aria-label="Permalink to &quot;1. Start from the Retro template&quot;">​</a></h2><ol><li>In your workspace, click <strong>New</strong>, then select <strong>New from template</strong>.</li><li>Open the <strong>Public gallery</strong> tab.</li><li>Find <strong>Retro (Start / Stop / Continue)</strong> and click <strong>Use</strong>.</li></ol><p>The board opens with a title and four sections: <strong>Start</strong>, <strong>Stop</strong>, <strong>Continue</strong>, and <strong>Action items</strong>. Each section has a prompt sticky note and an empty one.</p><p>If your gallery has no Retro template, create a board with <strong>New &gt; New board</strong> and add three sections named Start, Stop, and Continue. See <a href="/docs/board/sections.html#create-a-section">Sections</a>.</p><p><img src="'+r+`" alt="Retro board fresh from the template with Start, Stop, Continue, and Action items sections"></p><h2 id="_2-invite-your-team" tabindex="-1">2. Invite your team <a class="header-anchor" href="#_2-invite-your-team" aria-label="Permalink to &quot;2. Invite your team&quot;">​</a></h2><ol><li>Click <strong>Share</strong> in the top right.</li><li>Invite teammates or copy a link with editor access. See <a href="/docs/collaborate/share.html">Share a document</a>.</li></ol><p>When teammates join, you see their cursors and avatars.</p><h2 id="_3-add-sticky-notes" tabindex="-1">3. Add sticky notes <a class="header-anchor" href="#_3-add-sticky-notes" aria-label="Permalink to &quot;3. Add sticky notes&quot;">​</a></h2><ol><li>Double-click the empty sticky note in <strong>Start</strong> and type <code>Demo every Friday</code>.</li><li>Press <code>Tab</code>. A new green sticky note opens to the right. Type <code>Write release notes earlier</code>.</li><li>Press <code>Escape</code> to finish.</li><li>If a note lands outside the section, drag it in. A note belongs to a section once most of it is inside.</li></ol><p>To add several at once, copy this list, click empty canvas, and press <code>⌘+V</code> / <code>Ctrl+V</code>. Each line becomes a sticky note. Drag them into <strong>Stop</strong>.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Long stand-ups</span></span>
<span class="line"><span>Last-minute scope changes</span></span>
<span class="line"><span>Reviews waiting overnight</span></span></code></pre></div><h2 id="_4-group-the-duplicates" tabindex="-1">4. Group the duplicates <a class="header-anchor" href="#_4-group-the-duplicates" aria-label="Permalink to &quot;4. Group the duplicates&quot;">​</a></h2><ol><li>Drag sticky notes that say the same thing next to each other.</li><li>Select the notes in one section: click the first, then <code>Shift</code>-click the others.</li><li>Click <strong>Arrange</strong> in the top toolbar and select <strong>Tidy up</strong>.</li></ol><p>The notes line up in an even grid.</p><h2 id="_5-time-box-the-discussion" tabindex="-1">5. Time-box the discussion <a class="header-anchor" href="#_5-time-box-the-discussion" aria-label="Permalink to &quot;5. Time-box the discussion&quot;">​</a></h2><ol><li>Click <strong>Timer</strong> (the stopwatch icon) in the top toolbar.</li><li>Set <strong>Minutes</strong> to <code>5</code> and click <strong>Start</strong>.</li></ol><p>Everyone sees the countdown in the top-left corner of the canvas.</p><h2 id="_6-vote-on-what-to-act-on" tabindex="-1">6. Vote on what to act on <a class="header-anchor" href="#_6-vote-on-what-to-act-on" aria-label="Permalink to &quot;6. Vote on what to act on&quot;">​</a></h2><ol><li>Click <strong>Start voting…</strong> (the checklist icon) in the top toolbar.</li><li>Type <code>What should we act on first?</code>, keep <strong>Votes per person</strong> at 3, and click <strong>Start</strong>.</li><li>Click three sticky notes to vote on them. Click your own dot to take a vote back.</li><li>Click <strong>Done</strong>.</li><li>When everyone is done, click <strong>End voting</strong>.</li></ol><p>The <strong>Results</strong> card ranks the notes by votes. Click a row to jump to that note.</p><p><img src="`+s+'" alt="Voting card reading &quot;What should we act on first?&quot; with 2 of 3 votes left, and a vote dot on one sticky note"></p><h2 id="_7-write-the-action-items" tabindex="-1">7. Write the action items <a class="header-anchor" href="#_7-write-the-action-items" aria-label="Permalink to &quot;7. Write the action items&quot;">​</a></h2><ol><li>In <strong>Action items</strong>, double-click the sticky note <strong>Action, owner, due date</strong> and replace the text with <code>Demo every Friday, Alice, May 30</code>.</li><li>Press <code>Tab</code> to add the next action, and <code>Escape</code> when you finish.</li><li>Click <strong>Clear results</strong> on the <strong>Results</strong> card when you no longer need it.</li></ol><h2 id="_8-download-the-result" tabindex="-1">8. Download the result <a class="header-anchor" href="#_8-download-the-result" aria-label="Permalink to &quot;8. Download the result&quot;">​</a></h2><ol><li>Click <strong>Download</strong> (the download icon) in the top-right corner of the canvas.</li><li>Select <strong>Download as PDF</strong>.</li></ol><p>The PDF has the whole board on one page. Your board should look like this:</p><p><img src="'+i+'" alt="Finished retro board with stickies in Start, Stop, and Continue, tidied into grids, and two action items"></p><h2 id="next-steps" tabindex="-1">Next steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to &quot;Next steps&quot;">​</a></h2><ul><li><a href="/docs/board/facilitate-a-session.html">Facilitate a session</a> for stamps, spotlight, cursor chat, and comments.</li><li><a href="/docs/board/sections.html">Sections</a> to hide a section&#39;s notes until it is time to reveal them.</li><li><a href="/docs/board/keyboard-shortcuts.html">Keyboard shortcuts</a> to work faster.</li></ul>',33)])])}const k=e(l,[["render",c]]);export{b as __pageData,k as default};
